// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import type { Meta, StoryObj } from '@storybook/preact-vite';
import { action } from 'storybook/actions';
import { Input, InputProps } from '@adobe-commerce/elsie/components/Input';
import { Cart } from '@adobe-commerce/elsie/icons';
import { Icon } from '@adobe-commerce/elsie/components/Icon';
import { expect, userEvent, within } from 'storybook/test';
import { IconsList } from '@adobe-commerce/elsie/components/Icon/Icon.stories.helpers';

/**
 * Use Input to let users enter and edit text.
 */
const meta: Meta<InputProps> = {
  title: 'Components/Input',
  component: Input,
  argTypes: {
    name: {
      description: 'Field name (used for mapping the value in a form)',
      type: {
        required: false,
        name: 'string',
      },
    },
    value: {
      description: 'Field value',
      type: 'string',
    },
    variant: {
      description: 'Button variant: `primary`, or `secondary`',
      defaultValue: { summary: 'primary' },
      type: 'string',
      options: ['primary', 'secondary'],
      control: { type: 'radio' },
    },
    size: {
      options: ['medium', 'large'],
      control: { type: 'radio' },
    },
    placeholder: {
      description: 'placeholder text',
      control: 'text',
    },
    floatingLabel: {
      description: 'enable floating label',
      control: 'text',
    },
    disabled: {
      description: 'disable input field',
      control: 'boolean',
    },
    error: {
      description: 'enable error handling',
      control: 'boolean',
    },
    success: {
      description: 'enable success handling',
      control: 'boolean',
    },
    icon: {
      description: 'left ornamental icon',
      options: Object.keys(IconsList),
      mapping: IconsList,
      control: {
        type: 'select',
      },
    },
    // Add missing argTypes for InputProps
    onValue: {
      description: 'Callback function to handle value change',
      type: 'function',
    },
    maxLength: {
      description: 'Maximum length of the input field',
      type: 'number',
    },
    onUpdateError: {
      description: 'Callback function to handle error',
      type: 'function',
    },
    id: {
      description: 'Field id',
      type: {
        required: false,
        name: 'string',
      },
    },
  },
};

export default meta;

type Story = StoryObj<InputProps>;

export const Primary: Story = {
  args: {
    name: 'inputField',
    value: '',
    variant: 'primary',
    size: 'medium',
    floatingLabel: '',
    placeholder: 'Placeholder',
    disabled: false,
    error: false,
    success: false,
    onValue: action('onValue'),
    maxLength: 20,
    icon: <Icon source={Cart} />,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const inputField = document.querySelector('input') as HTMLElement;
    await userEvent.type(inputField, 'Storybook Test Text! input max length');
    await expect(
      await canvas.findByDisplayValue('Storybook Test Text!')
    ).toBeTruthy();
    await userEvent.clear(inputField);
    await expect(await canvas.findByDisplayValue('')).toBeTruthy();
  },
};

export const Secondary: Story = {
  args: {
    name: 'inputField',
    value: 'Storybook Test Text!',
    variant: 'secondary',
    size: 'medium',
    floatingLabel: '',
    placeholder: 'Placeholder',
    disabled: false,
    error: false,
    success: false,
    onValue: action('onValue'),
    maxLength: 20,
    icon: <Icon source={Cart} />,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const inputField = document.querySelector('input') as HTMLElement;
    await userEvent.type(inputField, 'Storybook Test Text! input max length');
    await expect(
      await canvas.findByDisplayValue('Storybook Test Text!')
    ).toBeTruthy();
    await userEvent.clear(inputField);
    await expect(await canvas.findByDisplayValue('')).toBeTruthy();
  },
};
